KEYS=sorted(W,key=lambda k:-len(k))
def seg(s):
    out=[];i=0;buf=''
    def flush():
        nonlocal buf
        if buf:
            r=conv(buf); out.append(r if r else buf); buf=''
    while i<len(s):
        for k in KEYS:
            if s.startswith(k,i):
                flush(); out.append(W[k]); i+=len(k); break
        else:
            buf+=s[i]; i+=1
    flush()
    return ' '.join(x.strip() for x in out if x.strip())
